const VM = ['voicemail_reached','voicemail'];
const out = [];
for (const item of $input.all()) {
  const root = item.json.call_id
    ? { event: 'call_analyzed', call: item.json }
    : ((item.json && item.json.body !== undefined && item.json.body !== null) ? item.json.body : (item.json || {}));
  const call = root.call || {};
  const meta = call.metadata || {};
  const vars = call.retell_llm_dynamic_variables || {};
  const analysis = call.call_analysis || {};
  const cad = analysis.custom_analysis_data || {};
  const reason = String(call.disconnection_reason || '');
  let outcome = String(cad.outcome || '').trim().toLowerCase();
  if (!outcome) {
    if (analysis.in_voicemail === true || VM.includes(reason)) outcome = 'voicemail';
    else outcome = 'no_answer';
  }
  const attemptRaw = Number(meta.attempt ?? vars.attempt ?? 1);
  out.push({ json: {
    event: String(root.event || item.json.event || ''),
    callId: String(call.call_id || ''),
    agentId: String(call.agent_id || ''),
